from taf.fdsw.rc.interfaces.FDSW23D.fdsw import FDSW23D
from taf.fdsw.rc.interfaces.FDSW24B.autoconnection import AutoConfiguration24B


class FDSW24B(FDSW23D):
    VERSION_NAME = 'FDSW24B'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW24B, self).__init__(ip_address=ip_address, port=port, username=username, password=password, secure=secure)
        self.autoconnection = AutoConfiguration24B(client=self._client)
